package companion

// Dashboard structure follows the Management Center's telemetry-first layout,
// with metrics sourced from this companion's own usage database and plan state.
const dashboardStyle = `<style>
.dashboard-page{position:relative;isolation:isolate;display:flex;flex-direction:column;gap:58px;max-width:1120px;margin:0 auto;padding-bottom:30px;--dash-green:#0f8f65;--dash-red:#c65746;--dash-amber:#ad7932;--dash-mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
.dashboard-page::before{content:"";position:absolute;z-index:-1;top:-35px;left:-20px;right:-20px;height:510px;background:radial-gradient(ellipse 60% 55% at 57% 15%,rgba(15,143,101,.095),transparent 78%),linear-gradient(90deg,rgba(45,42,38,.025) 1px,transparent 1px),linear-gradient(rgba(45,42,38,.025) 1px,transparent 1px);background-size:auto,72px 72px,72px 72px;mask-image:linear-gradient(to bottom,transparent,#000 20%,transparent 100%);pointer-events:none}
.dash-hero{position:relative;display:grid;grid-template-columns:minmax(0,1.2fr) minmax(300px,.8fr);align-items:center;gap:48px;min-height:310px;padding:24px 0 68px}.dash-hero-copy{position:relative;z-index:2}.dash-hero h1{margin:0;font-size:clamp(44px,5.5vw,76px);line-height:1.06;letter-spacing:-.055em;font-weight:740}.dash-period{color:var(--dash-green)}.dash-hero-meta{margin:19px 0 0;color:var(--muted);font:12px var(--dash-mono);letter-spacing:.02em}.dash-hero-desc{margin:14px 0 0;max-width:44ch;color:var(--muted);font-size:14px;line-height:1.65}.dash-actions{display:flex;align-items:center;gap:18px;flex-wrap:wrap;margin-top:28px}.dash-primary{display:inline-flex;align-items:center;min-height:41px;padding:10px 20px;border-radius:999px;background:var(--text);color:var(--bg);font-size:13px;font-weight:650;text-decoration:none}.dash-primary:hover{background:#48443f}.dash-quiet-link{color:var(--muted);font-size:13px;font-weight:600;text-decoration:none}.dash-quiet-link:hover{color:var(--text)}
.dash-hero-panel{position:relative;z-index:2;padding:27px 29px;border:1px solid rgba(213,210,203,.85);border-radius:20px;background:rgba(250,249,245,.85);box-shadow:0 18px 42px rgba(45,42,38,.085),0 2px 6px rgba(45,42,38,.04);backdrop-filter:blur(14px)}.dash-hero-panel-top{display:flex;justify-content:space-between;align-items:center;gap:10px}.dash-overline,.dash-eyebrow{font:700 11px var(--dash-mono);letter-spacing:.12em;color:var(--muted);text-transform:uppercase}.dash-live{display:inline-flex;align-items:center;gap:6px;padding:4px 9px;border:1px solid rgba(15,143,101,.25);border-radius:999px;background:rgba(15,143,101,.07);color:#087753;font:700 10px var(--dash-mono);letter-spacing:.1em}.dash-live::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--dash-green)}.dash-figure{display:block;margin-top:15px;font:600 clamp(46px,5vw,62px)/1 var(--dash-mono);letter-spacing:-.04em;font-variant-numeric:tabular-nums}.dash-window{display:block;margin-top:7px;color:var(--muted);font:12px var(--dash-mono)}.dash-ratio{display:flex;gap:2px;height:6px;margin:25px 0 13px;border-radius:4px;background:var(--border)}.dash-ratio span{display:block;min-width:0;border-radius:3px}.dash-ratio .ok{background:var(--dash-green)}.dash-ratio .bad{background:var(--dash-red)}.dash-split{display:flex;gap:22px;flex-wrap:wrap;padding-top:13px;border-top:1px solid var(--border);color:var(--muted);font-size:12px}.dash-split span{display:flex;align-items:center;gap:7px}.dash-split b{color:var(--text);font-family:var(--dash-mono)}.dash-dot{width:8px;height:8px;border-radius:2px;background:var(--dash-green)}.dash-dot.bad{background:var(--dash-red)}.dash-wire{position:absolute;z-index:1;left:0;right:0;bottom:-8px;width:100%;height:108px;overflow:visible}.dash-wire polyline{fill:none;stroke:rgba(15,143,101,.24);stroke-width:1.4;vector-effect:non-scaling-stroke}
.dash-controls{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-top:-16px}.dash-scope{color:var(--muted);font:11px var(--dash-mono)}.dash-tabs{display:flex;gap:5px;flex-wrap:wrap}.dash-tabs a{padding:7px 11px;border:1px solid var(--border-strong);border-radius:999px;color:var(--muted);font-size:11px;text-decoration:none}.dash-tabs a.active{border-color:var(--text);background:var(--text);color:var(--bg)}
.dash-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.dash-stat{display:flex;flex-direction:column;gap:6px;min-height:158px;padding:22px;border:1px solid var(--border);border-radius:14px;background:rgba(250,249,245,.84)}.dash-stat::before{content:"";width:28px;height:3px;margin-bottom:5px;border-radius:3px;background:var(--border-strong)}.dash-stat.green::before{background:var(--dash-green)}.dash-stat-label{color:var(--muted);font-size:12px;font-weight:650}.dash-stat-value{font:600 28px/1.15 var(--dash-mono);letter-spacing:-.04em;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.dash-stat-hint{margin-top:auto;color:var(--muted);font-size:11px}.dash-meter{height:5px;margin-top:4px;overflow:hidden;border-radius:4px;background:var(--border)}.dash-meter span{display:block;height:100%;background:var(--dash-green);border-radius:4px}
.dash-section{display:flex;flex-direction:column;gap:18px}.dash-section-head{display:grid;gap:5px}.dash-eyebrow::before{content:"▍";margin-right:6px;color:var(--dash-green)}.dash-section h2{margin:0;font-size:clamp(23px,2.5vw,29px);font-weight:680;letter-spacing:-.035em}.dash-section p{margin:0;color:var(--muted);font-size:13px}.dash-panel{padding:26px 28px;border:1px solid var(--border);border-radius:16px;background:rgba(250,249,245,.82)}
.dash-chart-legend{display:flex;gap:20px;flex-wrap:wrap;margin-bottom:22px;color:var(--muted);font-size:12px}.dash-chart-legend span{display:flex;align-items:center;gap:7px}.dash-chart-legend b{color:var(--text);font:600 12px var(--dash-mono)}.dash-chart{position:relative;display:flex;align-items:flex-end;gap:3px;height:224px;padding:0 2px 0;border-bottom:1px solid var(--border-strong);background:repeating-linear-gradient(to top,transparent 0,transparent 54px,var(--border) 55px,transparent 56px)}.dash-bar-col{height:100%;min-width:0;flex:1;position:relative}.dash-bar-stack{display:flex;flex-direction:column-reverse;justify-content:flex-start;gap:1px;height:100%}.dash-bar-stack span{display:block;min-height:0;border-radius:3px 3px 0 0;background:var(--dash-green)}.dash-bar-stack .fail{background:var(--dash-red)}.dash-bar-col:hover{background:rgba(15,143,101,.055)}.dash-chart-empty{position:absolute;inset:0;display:grid;place-items:center;color:var(--quiet);font-size:13px}.dash-axis{display:flex;justify-content:space-between;margin-top:12px;color:var(--quiet);font:11px var(--dash-mono)}
.dash-fleet{list-style:none;margin:0;padding:0}.dash-fleet li{display:grid;grid-template-columns:30px minmax(120px,1.3fr) minmax(90px,1fr) 80px 106px;align-items:center;gap:16px;padding:17px 0;border-bottom:1px solid var(--border)}.dash-fleet li:first-child{padding-top:0}.dash-fleet li:last-child{border:0;padding-bottom:0}.dash-rank{color:var(--quiet);font:600 12px var(--dash-mono)}.dash-provider-name{display:block;font-size:14px;font-weight:650;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.dash-provider-meta{display:block;margin-top:3px;color:var(--muted);font-size:11px}.dash-spark{width:100%;height:31px}.dash-spark polyline{fill:none;stroke:var(--dash-green);stroke-width:1.8;vector-effect:non-scaling-stroke}.dash-fleet-number{text-align:right}.dash-fleet-number b{display:block;font:600 15px var(--dash-mono)}.dash-fleet-number small{color:var(--muted);font-size:11px}.dash-fleet-rate b{font:600 12px var(--dash-mono)}.dash-fleet-rate .dash-meter{margin-top:7px}.dash-empty{padding:30px 0;color:var(--muted);text-align:center;font-size:13px}
.dash-details{display:grid;grid-template-columns:1fr 1fr;gap:16px}.dash-detail-head{margin-bottom:20px}.dash-detail-head h2{margin:5px 0 0;font-size:18px;font-weight:680;letter-spacing:-.02em}.dash-health-bar{display:flex;gap:2px;height:10px;margin-bottom:17px;border-radius:4px;background:var(--border)}.dash-health-bar .good{background:var(--dash-green);border-radius:4px}.dash-health-bar .quiet{background:var(--dash-amber);border-radius:4px}.dash-health-legend{display:flex;flex-wrap:wrap;gap:16px;color:var(--muted);font-size:12px}.dash-health-legend b{color:var(--text);font-family:var(--dash-mono)}.dash-spec{margin:0}.dash-spec div{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid var(--border);font-size:12px}.dash-spec div:last-child{border:0}.dash-spec dt{color:var(--muted)}.dash-spec dd{margin:0;font-weight:650;text-align:right;overflow-wrap:anywhere}.dash-detail-link{display:inline-block;margin-top:20px;color:#087753;font-size:12px;font-weight:650;text-decoration:none}.dash-detail-link:hover{text-decoration:underline}
.dash-next{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.dash-next a{position:relative;min-height:112px;padding:19px;border:1px solid var(--border);border-radius:14px;background:rgba(250,249,245,.82);text-decoration:none}.dash-next a:hover{border-color:var(--border-strong);background:#fff}.dash-next strong{display:block;font-size:13px}.dash-next span{display:block;margin-top:8px;color:var(--muted);font-size:11px;line-height:1.5}.dash-next i{position:absolute;right:17px;top:16px;font-style:normal;color:var(--muted)}.dash-note{margin-top:-30px;color:var(--quiet);font-size:11px;line-height:1.6}
@media(max-width:1050px){.dash-hero{grid-template-columns:1fr .9fr;gap:24px}.dash-fleet li{grid-template-columns:25px minmax(110px,1.3fr) 75px 85px}.dash-spark{display:none}}
@media(max-width:760px){.dashboard-page{gap:38px}.dash-hero{grid-template-columns:1fr;padding-bottom:35px}.dash-wire{height:75px;bottom:-4px}.dash-hero-panel{max-width:480px}.dash-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.dash-details{grid-template-columns:1fr}.dash-next{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:480px){.dash-hero h1{font-size:47px}.dash-hero-panel{padding:21px}.dash-stats{gap:9px}.dash-stat{min-height:145px;padding:16px}.dash-stat-value{font-size:24px}.dash-panel{padding:20px}.dash-fleet li{grid-template-columns:minmax(0,1fr) 75px 78px;gap:9px}.dash-rank{display:none}.dash-fleet-rate{min-width:0}.dash-chart{height:170px}.dash-next a{min-height:110px;padding:14px}}
</style>`

const usageDashboardTemplate = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>仪表盘 · CPA Companion</title>` + pageStyle + dashboardStyle + `</head><body><div class="shell"><aside class="sidebar"><a class="brand" href="/dashboard"><span class="brand-mark">C</span><span class="brand-copy"><span class="brand-title">CPA Companion</span>` + brandVersionTemplate + `</span></a><nav class="nav"><span class="nav-label">工作台</span><a class="nav-link active" aria-current="page" href="/dashboard">仪表盘</a><a class="nav-link" href="/keys">我的密钥</a>{{if .Admin}}<a class="nav-link" href="/admin">分流方案</a><a class="nav-link" href="/audit">内容审计</a>{{end}}<a class="nav-link" href="/prices">模型价格</a><a class="nav-link" href="/logs">使用日志</a></nav>` + sidebarGitHubTemplate + `<div class="sidebar-footer"><div class="identity"><span class="avatar"><span class="avatar-fallback">C</span>{{if .User.AvatarURL}}<img src="{{.User.AvatarURL}}" alt="" referrerpolicy="no-referrer">{{end}}</span><span class="identity-copy"><span class="identity-name">{{.User.Username}}</span><span class="identity-meta">{{.User.ID}}</span></span></div><form method="post" action="/auth/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="logout">退出登录</button></form></div></aside><main class="content"><div class="content-inner"><div class="dashboard-page">
<section class="dash-hero"><div class="dash-hero-copy"><h1>{{.Verdict}}<span class="dash-period">。</span></h1><p class="dash-hero-meta">CPA COMPANION · {{.ScopeText}} · 北京时间</p><p class="dash-hero-desc">实时掌握 API 请求、上游账号和分流方案的运行状态。</p><div class="dash-actions"><a class="dash-primary" href="/keys">管理我的密钥</a><a class="dash-quiet-link" href="/logs">查看使用日志 →</a></div></div><div class="dash-hero-panel"><div class="dash-hero-panel-top"><span class="dash-overline">请求总数</span><span class="dash-live">LIVE</span></div><strong class="dash-figure">{{.RecentRequests}}</strong><span class="dash-window">最近 6 小时 · 10 分钟粒度</span><div class="dash-ratio" aria-hidden="true"><span class="ok" style="width:{{.SuccessWidth}}%"></span><span class="bad" style="width:{{.FailureWidth}}%"></span></div><div class="dash-split"><span><i class="dash-dot"></i>成功 <b>{{.RecentSuccess}}</b></span><span><i class="dash-dot bad"></i>失败 <b>{{.RecentFailure}}</b></span></div></div><svg class="dash-wire" viewBox="0 0 100 28" preserveAspectRatio="none" role="img" aria-label="最近六小时请求趋势"><polyline points="{{.WirePoints}}"></polyline></svg></section>
<div class="dash-controls"><span class="dash-scope">以下用量指标：最近 6 小时 · {{.ScopeText}}</span>{{if .Admin}}<div class="dash-tabs"><a href="/dashboard" class="{{if not .All}}active{{end}}">我的数据</a><a href="/dashboard?scope=all" class="{{if .All}}active{{end}}">全部用户</a></div>{{end}}</div>
<section class="dash-stats" aria-label="运行指标"><article class="dash-stat green"><span class="dash-stat-label">成功率</span><strong class="dash-stat-value">{{.SuccessRate}}%</strong><div class="dash-meter" aria-hidden="true"><span style="width:{{.SuccessRate}}%"></span></div><span class="dash-stat-hint">{{.RecentRequests}} 次请求 · 最近 6 小时</span></article><article class="dash-stat"><span class="dash-stat-label">分配的上游账号</span><strong class="dash-stat-value">{{.Assigned}}</strong><div class="dash-meter" aria-hidden="true"><span style="width:{{.ActivePercent}}%"></span></div><span class="dash-stat-hint">当前可用 {{.ActiveAccounts}} 个</span></article><article class="dash-stat"><span class="dash-stat-label">我的 API Key</span><strong class="dash-stat-value">{{.KeyCount}}</strong><span class="dash-stat-hint">由当前账号创建和管理</span></article><article class="dash-stat"><span class="dash-stat-label">已使用模型</span><strong class="dash-stat-value">{{.ModelCount}}</strong><span class="dash-stat-hint">当前统计范围内的不同模型</span></article></section>
<section class="dash-section"><header class="dash-section-head"><span class="dash-eyebrow">实时流量</span><h2>请求吞吐</h2><p>最近 6 小时，以 10 分钟为粒度；绿色为成功，红色为失败。</p></header><div class="dash-panel"><div class="dash-chart-legend"><span><i class="dash-dot"></i>成功 <b>{{.RecentSuccess}}</b></span><span><i class="dash-dot bad"></i>失败 <b>{{.RecentFailure}}</b></span></div><div class="dash-chart" role="img" aria-label="最近六小时每十分钟请求成功与失败数量">{{range .Traffic}}<div class="dash-bar-col" title="{{.Label}} · 成功 {{.Success}} · 失败 {{.Failed}}"><div class="dash-bar-stack"><span style="height:{{.SuccessHeight}}%"></span><span class="fail" style="height:{{.FailedHeight}}%"></span></div></div>{{end}}{{if not .RecentRequests}}<div class="dash-chart-empty">暂无请求，流量会在这里出现。</div>{{end}}</div><div class="dash-axis"><span>{{(index .Traffic 0).Label}}</span><span>{{(index .Traffic 18).Label}}</span><span>{{(index .Traffic 36).Label}}</span></div></div></section>
<section class="dash-section"><header class="dash-section-head"><span class="dash-eyebrow">上游</span><h2>供应商对比</h2><p>按最近 6 小时请求量排序；账号数来自当前 CPA 账号目录。</p></header><div class="dash-panel">{{if .Providers}}<ol class="dash-fleet">{{range $index,$provider := .Providers}}<li><span class="dash-rank">{{if lt $provider.Rank 10}}0{{end}}{{$provider.Rank}}</span><div><strong class="dash-provider-name">{{$provider.Name}}</strong><span class="dash-provider-meta">{{$provider.Accounts}} 个账号</span></div><svg class="dash-spark" viewBox="0 0 100 28" preserveAspectRatio="none" aria-hidden="true"><polyline points="{{$provider.Points}}"></polyline></svg><div class="dash-fleet-number"><b>{{$provider.Requests}}</b><small>次请求</small></div><div class="dash-fleet-rate"><b>{{$provider.Rate}}%</b><div class="dash-meter"><span style="width:{{$provider.Rate}}%"></span></div></div></li>{{end}}</ol>{{else}}<div class="dash-empty">暂无上游账号信息。</div>{{end}}</div></section>
<section class="dash-details"><div class="dash-panel"><header class="dash-detail-head"><span class="dash-eyebrow">健康度</span><h2>账号与方案状态</h2></header><div class="dash-health-bar" aria-hidden="true"><span class="good" style="width:{{.ActivePercent}}%"></span><span class="quiet" style="width:{{.InactivePercent}}%"></span></div><div class="dash-health-legend"><span><i class="dash-dot"></i> 可用 <b>{{.ActiveAccounts}}</b></span><span><i class="dash-dot" style="background:var(--dash-amber)"></i> 暂不可用 <b>{{.InactiveAccounts}}</b></span></div><dl class="dash-spec"><div><dt>当前方案</dt><dd>{{if .HasPlan}}{{.PlanName}}{{else}}未分配{{end}}</dd></div><div><dt>方案状态</dt><dd>{{.PlanStatus}}</dd></div></dl><a class="dash-detail-link" href="/keys">查看我的账号 →</a></div><div class="dash-panel"><header class="dash-detail-head"><span class="dash-eyebrow">运行时</span><h2>使用概况</h2></header><dl class="dash-spec"><div><dt>统计范围</dt><dd>最近 6 小时 · {{.ScopeText}}</dd></div><div><dt>输入 Token</dt><dd>{{.Summary.InputTokens}}</dd></div><div><dt>输出 Token</dt><dd>{{.Summary.OutputTokens}}</dd></div><div><dt>预估费用</dt><dd>${{.Summary.CostUSD}}</dd></div>{{if .HasBudget}}<div><dt>方案累计额度</dt><dd>${{.Used}} / ${{.Budget}}</dd></div>{{end}}</dl><a class="dash-detail-link" href="/logs">查看请求明细 →</a></div></section>
<section class="dash-section"><header class="dash-section-head"><span class="dash-eyebrow">下一步</span><h2>接下来去哪里</h2></header><div class="dash-next"><a href="/keys"><i>↗</i><strong>我的密钥</strong><span>复制或轮换 API Key，查看分配的上游。</span></a>{{if .Admin}}<a href="/admin"><i>↗</i><strong>分流方案</strong><span>管理方案、上游账号与可用时间。</span></a>{{end}}<a href="/prices"><i>↗</i><strong>模型价格</strong><span>查看模型计费表达式与费用规则。</span></a><a href="/logs"><i>↗</i><strong>使用日志</strong><span>按模型、状态和时间检索请求。</span></a></div></section><p class="dash-note">请求与费用统计从启用 SQL 日志后开始；价格按请求完成时的配置记录，历史请求不会回填。</p>
</div></div></main></div>` + navigationScript + `</body></html>`
